import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxPagination,
  JxEmptyState,
  JxBadge,
  JxButton,
  JxBadgeTone,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  over: 'Квота превышена',
};

const STATUS_TONE: Record<ProjectStatus, JxBadgeTone> = {
  active: 'success',
  warning: 'warning',
  over: 'danger',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Мобильное приложение', quota: 42, status: 'active' },
  { id: 'p2', name: 'Аналитика продаж', quota: 78, status: 'warning' },
  { id: 'p3', name: 'Внутренний портал', quota: 105, status: 'over' },
  { id: 'p4', name: 'Платёжный шлюз', quota: 30, status: 'active' },
  { id: 'p5', name: 'Маркетинг-сайт', quota: 88, status: 'warning' },
  { id: 'p6', name: 'CRM интеграция', quota: 61, status: 'active' },
  { id: 'p7', name: 'Логистика', quota: 97, status: 'warning' },
  { id: 'p8', name: 'Склад', quota: 112, status: 'over' },
  { id: 'p9', name: 'Поддержка клиентов', quota: 55, status: 'active' },
  { id: 'p10', name: 'Отчётность', quota: 73, status: 'warning' },
  { id: 'p11', name: 'Биллинг', quota: 40, status: 'active' },
  { id: 'p12', name: 'Архив документов', quota: 120, status: 'over' },
];

const ALL_STATUSES: ProjectStatus[] = ['active', 'warning', 'over'];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((p) => activeStatuses.includes(p.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-lg, 16px)',
        padding: 'var(--jx-space-lg, 16px)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-space-sm, 8px)', flexWrap: 'wrap' }}>
        {ALL_STATUSES.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm, 8px)' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-md, 12px)',
                  padding: 'var(--jx-space-md, 12px)',
                  borderRadius: 'var(--jx-radius-md)',
                  border: '1px solid var(--jx-border-color)',
                }}
              >
                <span>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-md, 12px)' }}>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={STATUS_TONE[project.status]} dot>
                    {STATUS_LABEL[project.status]}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

